package com.huiqiyikang.assessment.service;
import com.huiqiyikang.assessment.entity.Question; import com.huiqiyikang.assessment.mapper.QuestionRepository; import org.springframework.stereotype.Service; import java.util.*;
@Service public class QuestionService { private final QuestionRepository mapper; public QuestionService(QuestionRepository mapper){this.mapper=mapper;} public List<Question> list(Long uid){return mapper.findByOwnerUserIdAndStatus(uid,"active");} public List<Question> findByOwnerUserIdAndStatus(Long uid,String status){return mapper.findByOwnerUserIdAndStatus(uid,status);} public List<Question> publicList(){return mapper.findByVisibilityAndStatus("public","active");} public List<Question> findByVisibilityAndStatus(String v,String s){return mapper.findByVisibilityAndStatus(v,s);} public Optional<Question> find(Long id){return mapper.findById(id);} public Optional<Question> findById(Long id){return mapper.findById(id);} public Question save(Question q){return mapper.save(q);} }
